const VOICE_TTS_EMOTIONS = new Set(['auto', 'happy', 'sad', 'angry', 'fearful', 'disgusted', 'calm']);
function isScheduleOnDate(schedule, date = new Date()) {
    if (schedule?.dateISO) return schedule.dateISO === getLocalDateKey(date);
    return isLegacyScheduleOnDateKey(schedule?.date, getLocalDateKey(date));
}
function resolveScheduleDateISO(dayValue, reference = new Date()) {
    const day = Number.parseInt(String(dayValue || '').replace(/\D/g, ''), 10);
    if (!Number.isInteger(day) || day < 1 || day > 31) return getLocalDateKey(reference);
    const candidates = [-1, 0, 1].map(monthOffset => {
        const value = new Date(reference.getFullYear(), reference.getMonth() + monthOffset, day);
        return { value, distance: Math.abs(value.getTime() - reference.getTime()) };
    }).filter(item => item.value.getDate() === day);
    candidates.sort((a, b) => a.distance - b.distance);
    return getLocalDateKey(candidates[0]?.value || reference);
}
function isLegacyScheduleOnDateKey(dayValue, dateKey) {
    const todayKey = getLocalDateKey();
    return String(dateKey).slice(0, 7) === todayKey.slice(0, 7)
        && String(dateKey) <= todayKey
        && String(dayValue || '') === String(Number(String(dateKey).slice(8, 10)));
}
const activeImageGenerations = new Map();
