                                    const imgChars = new Set(imgDesc.split(''));
                                    let overlap = 0;
                                    for (const ch of descChars) { if (imgChars.has(ch)) overlap++; }
                                    const score = overlap / (descChars.size || 1);
                                    if (score > bestScore && score > 0.15) {
                                        bestScore = score;
                                        matched = img;
                                    }
