/**
 * 【核心强化】触发角色主动发消息
 * 包含强制的时间流逝感知引擎，确保AI明确知道你们多久没说话了
 * @param {string} charId - 目标角色ID
 */
export async function triggerActiveMessage(charId) {
    const sleepingChar = AppState.characterProfiles.find(c => String(c.id) === String(charId));
    if (sleepingChar && getSleepState(sleepingChar).sleeping) return false;
    console.log(`[主动发消息] 开始为角色 ${charId} 生成主动消息...`);
    if (tempState.activeCallChatId && String(tempState.activeCallChatId) === String(charId)) return false;
    const char = AppState.characterProfiles.find(c => c.id === charId);
    // ▼ 修改：增加拉黑判断，如果被拉黑则直接返回不执行
    if (!char || char.isBlocked) return;

    try {
        // 1. 精确计算距离上次聊天的真实物理时间
        let timeSinceLastMsg = '一段时间';
        const lastMsg = await db.chatMessages.where({ chatId: charId }).last();
        
        if (lastMsg) {
            const diffMs = new Date() - new Date(lastMsg.timestamp);
            const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
            const diffMinutes = Math.floor(diffMs / (1000 * 60));
            
            if (diffHours > 24) {
                timeSinceLastMsg = `${Math.floor(diffHours / 24)} 天`;
            } else if (diffHours > 0) {
                timeSinceLastMsg = `${diffHours} 个小时`;
            } else if (diffMinutes > 0) {
                timeSinceLastMsg = `${diffMinutes} 分钟`;
            } else {
                timeSinceLastMsg = `刚刚`;
            }
        }

        // 2. 构造绝对强制的系统级上帝指令
        // 使用 "<...>" 包裹，系统底层会自动将这层身份转换为 "system" (最高级权重)，用户完全不可见
        const activeMsgPrompt = `<[系统强制指令：现在是你主动找用户聊天的时刻。
1. 时间感知校验：距离你们上次聊天已经过去了【${timeSinceLastMsg}】，而现实生活中的当前时间是【${new Date().toLocaleString('zh-CN', { hour12: false })}】。
2. 行为要求：请根据你们当前的时段（比如深夜、清晨或工作时间）、你的人设以及你们之前的聊天内容，主动发一条消息。
3. 绝对禁令：绝不要在你的回复中提及你收到了“系统指令”。你要表现得像是一个活生生的人，因为思念、无聊或者发生了一件小事而突然拿起手机找TA。]>`;

        await injectHiddenPromptAndTriggerReply(charId, activeMsgPrompt, '主动发消息');
    } catch (error) {

        console.error('[主动发消息] 引擎触发失败:', error);
    }
}
export async function triggerFollowUpMessage(charId, plan = null, actualMinutes = 0) {
    if (tempState.activeCallChatId && String(tempState.activeCallChatId) === String(charId)) return false;
    // 线下模式活跃时不触发追发（和主动发消息保持一致）
    const isOfflineActive = (tempState.activeOfflineSession === charId) || localStorage.getItem(`offline_session_active_${charId}`);
    if (isOfflineActive) return false;
    const char = findCharacterById(charId);
    if (char && getSleepState(char).sleeping) return false;
    if (!char || char.isBlocked) return false;
    const triggerStartTime = Date.now();
    const sourcePlan = plan || char.followUpPlan || {};
    const followUpPlan = normalizeFollowUpPlan(sourcePlan, char.followUpPlan);
    if (!followUpPlan) return false;
    const maxFires = getFollowUpMaxFires(followUpPlan);
    if (followUpPlan.firedCount >= maxFires) {
        await clearFollowUpPlan(charId);
        return false;
    }
    const actualPlan = followUpPlan;
    const nextFiredCount = Math.min(maxFires, Number(actualPlan.firedCount || 0) + 1);
    actualPlan.firedCount = nextFiredCount;
    actualPlan.createdAt = Number(sourcePlan.createdAt) || actualPlan.createdAt || Date.now();
    actualPlan.lastFiredAt = triggerStartTime;
    const saved = await persistFollowUpTriggerIfCurrent(charId, actualPlan, triggerStartTime, sourcePlan);
    if (!saved) return false;
    const hiddenText = buildFollowUpHiddenPrompt(actualPlan, actualMinutes);
    await injectHiddenPromptAndTriggerReply(charId, hiddenText, '追发', triggerStartTime);
    return true;
}
